\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Pergament}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5706[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 I + 129 Bl.}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5360[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 24,5 x 15,5}}\plain \f1\lang1033\fs24   cm. (I+1)\plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24   + 12 V\plain \f1\super\lang1033\fs24 122\plain \f1\lang1033\fs24   + (V\endash 3)\plain \f1\super\lang1033\fs24 129\plain \f1\lang1033\fs24 . Schriftspiegel: 16,5 x 9,5 cm (Haupttext; mit Randkommentar: 16,5 x 13,5 cm). 1 Spalte. 23 Zeilen. {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Humanistische Minuskel}}\plain \f1\lang1033\fs24   von der Hand des {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Giovan Marco Cinico}}\plain \f1\lang1033\fs24   aus Parma, der 1462-1497 in Neapel f\u252 \'fcr das K\u246 \'f6nigshaus t\u228 \'e4tig war (signiert auf Bl. 129\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ). Von ihm auch Anfang und Ende der Kapitel in farbiger Capitalis, Versalien, Majuskeln im Flie\u223 \'dftext, Randkommentare (meist figurative Schriftfl\u228 \'e4che, vor allem blockartig oder als Dreieck) und Seitentitel (Buchz\u228 \'e4hlung beidseitig oben) in den Farben Dunkelrot, Orange (bzw. r\u246 \'f6tliches Hellbraun), Olivgr\u252 \'fcn, Blaugr\u252 \'fcn, Hellblau (auch Zeilenf\u252 \'fcllornamente, s.u.). {\field{\*\fldinst HYPERLINK "hida://5300[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Goldschnitt}}\plain \f1\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

