\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Hinweise auf erste Schemata; drei Definitionen. 2\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24  kurzes Inhaltsverzeichnis. 2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 129\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Raimundus Lullus}}\plain \f1\lang1033\fs24   (2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Lectura brevis artis compendiosae inveniendi veritatem}}\plain \f1\lang1033\fs24  ; 4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacant; 5\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 27\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ars compendiosa minor inveniendi veritatem}}\plain \f1\lang1033\fs24  ; 28\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 46\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Liber propositionum secundum artem demonstrativam}}\plain \f1\lang1033\fs24  ; 46\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 128\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Compendium artis demonstrative}}\plain \f1\lang1033\fs24  ; 128\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat; 129\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   Ars compendiosa minor inveniendi veritatem [Fragment]). 130\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 131\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. Siehe \plain \f1\scaps\lang1033\fs24 Perarnau\plain \f1\lang1033\fs24 .}

