\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   schemenartiger \u220 \'dcberblick \u252 \'fcber Themen der Hs. (in roter und brauner Tinte). 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Notiz zu Perceval Spinola (s. o.). 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 61\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Raimundus Lullus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Liber de ascensu et descensu intellectus}}\plain \f1\lang1033\fs24 . 61\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 64\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Idem, {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De demonstratione per aequiparantiam}}\plain \f1\lang1033\fs24 . 64\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 65\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. Siehe auch \plain \f1\scaps\lang1033\fs24 Perarnau\plain \f1\lang1033\fs24 .}

