\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 152\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Publius Papinius Statius}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Argumentum Thebaidos}}\plain \f1\lang1033\fs24   (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 12\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch 1; 12\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch 2; 24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 35\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch 3; 35\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 49\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch 4; 49\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 60\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch 5; 60\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 84\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   [alt 74\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  ] Buch 6; 84\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   [alt 74\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  ]\endash 77\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24  [alt 87\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  ] Buch 7; 77\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24  [alt 87\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  ]\endash 99\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch 8; 99\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 113\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch 9; 113\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 128\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch 10; 128\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 139\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch 11; 140\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 152\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch 12). Bl. 152\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 153\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   drei italienische {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Gedichte}}\plain \f1\lang1033\fs24   von {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Francesco Negusanti}}\plain \f1\lang1033\fs24   (darin werden sein Name und Bologna bzw. Fano genannt). 153\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Ausschnitte aus der Vita Statii (vom ersten Schreiber). 154\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant.}

