\uc1
\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24 : 1\endash 5-zeilige rote und blaue Lombarden im Wechsel (Init.-H\u246 \'f6he: 0,5\endash 3 cm), mit Fleuronn\u233 \'e9e: lilafarben bei den roten bzw. rot bei den blauen Initialen. Besatz und Binnenraum: etwa auf H\u246 \'f6he der Initiale mehrere gerade vertikale Parallelf\u228 \'e4den, au\u223 \'dfen teils behaftet mit unterschiedlich gro\u223 \'dfen Perlen. }

