\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash II\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 69\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Gaius Sollius Apollinaris Sidonius}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Briefe}}\plain \f1\lang1033\fs24   (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 10\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24  Buch 1; 10\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 18\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24  Buch 2; 18\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 24\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24  Buch 3; 24\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 36\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24  Buch 4; 36\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 44\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24  Buch 5; 44\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 55\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24  Buch 6; 55\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 59\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24  Buch 7; 59\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 69\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24  Buch 8). 69\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 70\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant.}

