\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Ausstattung\plain \f1\lang1033\fs24 : Zahlreiche kleine Fleuronn\u233 \'e9e-Initialen. 5 gro\u223 \'dfe Fleuronn\u233 \'e9e-Initialen. 2 schlichte Schemata in brauner Tintenzeichnung (sehr wenig rot erg\u228 \'e4nzt). Gelegentlich dilettantische Randzeichnungen in brauner Tinte (z. B. Zeigeh\u228 \'e4nde [Bl. 55\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  ], verschieden verzierte Nota- und Quaestioneszeichen [45\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 46\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 62\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  ]).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

