\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   zwei Exlibris (s. o.). II\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Vorspann von Hartmann Schedel (s. o.). II\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   eigenh\u228 \'e4ndiger Besitzvermerk (s. o.). III\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24   Titelnennung. III\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24  medizinisches Rezept. IV\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacat. IV\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   erneuter Besitzeintrag Schedels. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 86\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes Iamatus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Chirurgia}}\plain \f1\lang1033\fs24   (bzw. Thesaurus secretorum). 86\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Rezepte. 87\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacat. 87\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Rezept. 88\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Titelnennung. 88\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 89\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant.}

