\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 45\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Eusebius Cremonensis}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Epistola ad beatum Damasium Portuensem de morte sancti Hieronymi}}\plain \f1\lang1033\fs24 . 45\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 53\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ps.-Augustinus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Epistola ad Cyrillum}}\plain \f1\lang1033\fs24 . 53\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 60\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cyrillus Hierosolymitanus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Epistola ad sanctum Augustinum}}\plain \f1\lang1033\fs24 . 61\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De obitu beati Eusebii}}\plain \f1\lang1033\fs24 . 61\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 93\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   anonyme Briefe und Heiligenlegenden.}

