\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Ausstattung\plain \f1\lang1033\fs24 : 1 Fleuronn\u233 \'e9e-Initiale von italienischer Hand (gelegentlich kleine, wohl italienische Zierelemente, z. B. Bl. 20\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ). Bl. 147\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   rote Lombarde mit blauem Fleuronn\u233 \'e9e (6-zeilig; Init.-H\u246 \'f6he: 3,5 cm). Besatz: blockartige Erweiterung durch mehrere rechteckig zueinander stehende Parallelf\u228 \'e4den, an denen teilweise au\u223 \'dfen Perlenketten mit abstehenden F\u228 \'e4den und Zacken anhaften. Binnenraum: Quadratmuster aus dunkel grundierten Sternbl\u252 \'fcten. 1 Titelschmuck mit historisierter Initiale und Wappen in Deckfarben und Pinselgold. Schlichte Reklamantenverzierungen in roter, blauer und brauner Tinte (einfache rechteckige bzw. leicht geschwungene Rahmen mit getrepptem Aufsatz). 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 [Zahlreiche Fleuronn\u233 \'e9e-Initialen (z. B. 36\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 41\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 112\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ), deutsch, 15. Jh.]}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Titelschmuck mit {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 historisierter Initiale}}\plain \f1\lang1033\fs24  und Wappen: 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Autorenprofil, in A (\plain \f1\i\lang1033\fs24  interdum includit ut C\plain \f1\lang1033\fs24 ). 16-zeilige Initiale (H\u246 \'f6he: 6,5 cm) mit schlichtem rosafarbenen Stamm vor rechteckigem blauen Feld, das an den linken Ecken durch vegetabile Ausl\u228 \'e4ufer vom Initialstamm durchbrochen wird und in vertikale Randbord\u252 \'fcre \u252 \'fcbergeht: umrankt von gro\u223 \'dfz\u252 \'fcgig gemalten (im dar\u252 \'fcbergelegten Wei\u223 \'dflinienprofil klareren) glattrandigen und weich gelappten Profilbl\u228 \'e4ttern, T\u252 \'fctenbl\u228 \'e4ttern und ovalen Blattmanschetten ergeben sich blaue und rosafarbene tropfenf\u246 \'f6rmige Felder mit Wei\u223 \'dflinienfiligran. Binnenraum: {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Halbfigur}}\plain \f1\lang1033\fs24   des Johannes Calderinus in strengem Profil nach links, bekleidet mit rotem {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Mantel}}\plain \f1\lang1033\fs24   und roter {\field{\*\fldinst HYPERLINK "hida://5500[2]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 M\u252 \'fctze}}\plain \f1\lang1033\fs24 , vor blauem Grund. Au\u223 \'dfer der Figur alles mit grobem Wei\u223 \'dflinienfiligran (Fadenranken, Punkte) bedeckt. \endash  Fu\u223 \'df der Seite: waagrechte Rankenbord\u252 \'fcre mit Blattwerk vor blauen Feldern mit Wei\u223 \'dflinienfiligran, in der Mitte 8-eckiger Stern in Rosa, mit dem Wappen des Johannes Gwerlich (aufsteigendes schwarzes Einhorn auf wei\u223 \'dfem Schild). }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 @Arial Unicode MS;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;\red51\green51\blue51;}

