\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24 : 4\endash 6-zeilige rote und blaue Lombarden im Wechsel (Init.-H\u246 \'f6he: 2\endash 2,5 cm), mit rotem Fleuronn\u233 \'e9e in den blauen und braunem Fleuronn\u233 \'e9e in den roten Initialen. Besatz und Binnenraum: Dicht nebeneinander mehrere Parallelf\u228 \'e4den in Initialh\u246 \'f6he, nach au\u223 \'dfen hin besetzt mit Perlen oder gebogter Linie, links unten Einzelfaden in gr\u246 \'f6\u223 \'dferer Schlinge als Ausl\u228 \'e4ufer.}

