\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Goldinitialen mit Wei\u223 \'dfranken}}\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24 und Titelschmuck\plain \f1\scaps\lang1033\fs24 : \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Gro\u223 \'dfe Anfangsinitiale in Blattgold (8-zeilig; Init.-H\u246 \'f6he: 4,5 cm) vor rechteckigem, unregelm\u228 \'e4\u223 \'dfig konturiertem Feld und \endash  davon ausgehend \endash  den Schriftspiegel links vertikal sowie am Fu\u223 \'df der Seite flankierende Bord\u252 \'fcren mit Wei\u223 \'dfranken vor Deckfarbengrund (mit wei\u223 \'dfem Streumuster: Punktreihen und -gruppen), teils ges\u228 \'e4umt von Goldpollen (einzeln und in Gruppen) mit dichtem Wimpernbesatz; zentral am Fu\u223 \'df der Seite das Wappen von Matthias Corvinus in Rundpass, umrahmt von Blattkranz zwischen zwei Goldleisten. Wappentyp B (siehe \plain \f1\scaps\lang1033\fs24 Csapodi-G\plain \f1\scaps\lang1033\fs24 \u225 \'e1\plain \f1\scaps\lang1033\fs24 rdonyi\plain \f1\lang1033\fs24   1969).
