\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Mittelbrauner Ledereinband}}\plain \f1\lang1033\fs24   mit {\field{\*\fldinst HYPERLINK "hida://5300[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Streicheisenlinien}}\plain \f1\lang1033\fs24   (Streifenrahmen; Mittelfeld mit Rautenmuster [3 : 3]) und {\field{\*\fldinst HYPERLINK "hida://5300[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Einzelstempeln}}\plain \f1\lang1033\fs24   (Namen \plain \f1\i\lang1033\fs24  maria\plain \f1\lang1033\fs24   auf geschwungenem, umrandeten Schriftband; Doppellilie in umrandetem Rhombus; kleine 5-bl\u228 \'e4ttrige Rosette), N\u252 \'fcrnberg, letztes Viertel 15. Jh. Auf Vorderdeckel Pergamentstreifen (beschriftet: \plain \f1\i\lang1033\fs24  Lucanus\plain \f1\lang1033\fs24 ) aufgeklebt. Auf dem R\u252 \'fccken altes Bibliotheksschildchen. {\field{\*\fldinst HYPERLINK "hida://599a[0].599e/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1951 restauriert}}\plain \f1\lang1033\fs24 .}

