\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt:\plain \f1\lang1033\fs24   I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash IV\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacant. IV\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Epitaph auf den 1413 verstorbenen Autor Jacobus de Forlivio, der in der Eremitanikirche in Padua bestattet wurde. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 173\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Jacobus de Forlivio}}\plain \f1\lang1033\fs24 .\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 79\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Super aphorismis Hippocratis}}\plain \f1\lang1033\fs24 . 79\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 80\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. 81\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 172\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Quaestiones}}\plain \f1\lang1033\fs24 . 172\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 173\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Dubia}}\plain \f1\lang1033\fs24 . 174\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 175\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   alphabetische Tabula (unvollendet). 175\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 184\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  