\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\scaps\lang1033\fs24 :\plain \f1\lang1033\fs24   3\endash 15-zeilige rote und blaue Lombarden (H\u246 \'f6he: 1,5\endash 6 cm), mit dunkelrotem Fleuronn\u233 \'e9e. Besatz und Binnenraum: geb\u252 \'fcndelt mehrere vertikale Parallelst\u228 \'e4be, an denen au\u223 \'dfen Einzelperlen oder flache B\u246 \'f6gen mit Kern (Punkte, einzeln oder als Kette) sitzen, wobei der linke Stab entweder unten in einem nach au\u223 \'dfen gekurvten Einzelfaden endet oder oben und unten durch einen schr\u228 \'e4gen Bogen abgeschlossen wird (nicht exakt, da die Einzelf\u228 \'e4den leicht \u252 \'fcberragen).}

