\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f2\scaps\lang1033\fs24 Von Schulte, \plain \f2\lang1033\fs24 Bd. 1, 1875, S. 298. \endash  \plain \f2\scaps\lang1033\fs24 E.W. Bredt\plain \f2\lang1033\fs24 , Der Handschriftenschmuck Augsburgs im XV. Jahrhundert (Studien zur deutschen Kunstgeschichte 25). Stra\u223 \'dfburg 1900, S. 19. \endash  \plain \f2\scaps\lang1033\fs24 L. Baer\plain \f2\lang1033\fs24 , in: ThB 23, 1929, S. 312. \endash  \plain \f2\scaps\lang1033\fs24 A. Belloni\plain \f2\lang1033\fs24 , Professori giuristi a Padova nel secolo XV. Profili bio-bibliografici e cattedre. Frankfurt 1986, S. 241. \endash  \plain \f2\scaps\lang1033\fs24 Rauner\plain \f2\lang1033\fs24  2007, S. 540f.}

