\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Eigenh\u228 \'e4ndiger Eintrag des Andreas von Regensburg (30er Jahre des 15. Jhs.; siehe darunterstehenden Bleistiftvermerk von Leidinger, 1903). I\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash II\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 139\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes Andreae}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Novella}}\plain \f1\lang1033\fs24 . 139a\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant. 140\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 212\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24  Johannes Andreae,\plain \f2\lang1033\fs20\cf18  {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Questiones Mercuriales de regulis iuris}}\plain \f1\lang1033\fs24 . 212\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 213\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 216\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Inhalts\u252 \'fcberblick. 216\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 219\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Rubrikenverzeichnis. 220\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant.}

