\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Ausstattung\plain \f1\lang1033\fs24 : Zahlreiche Fleuronn\u233 \'e9e-Initialen. 1 Ornamentinitiale und 1 Miniatur in Deckfarben, Silber und Pinselgold. 1 Titelschmuck mit historisierter Initiale und Wappen in Deckfarben, Silber, Pinsel- und Blattgold. Dilettantische Zeigeh\u228 \'e4nde in brauner Tinte (z. B. 3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 9\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 235\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24 : 3\endash 6-zeilige rote und blaue Lombarden im Wechsel (Init.-H\u246 \'f6he: 1\endash 3 cm), mit braunem bzw. rotem Fleuronn\u233 \'e9e. Besatz und Binnenraum: in H\u246 \'f6he der Initiale mehrere vertikale Parallelf\u228 \'e4den, au\u223 \'dfen mit einzelnen Perlen besetzt und nach links unten in einen l\u228 \'e4ngeren Ausl\u228 \'e4ufer mit Haarnadelkurve endend.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

