\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24 : 2\endash 3-zeilige rote und blaue Lombarden im Wechsel (Init.-H\u246 \'f6he: 1\endash 1,5 cm), mit braunem (bei den roten Initialen) bzw. rotem (bei den blauen Initialen) Fleuronn\u233 \'e9e. Besatz und Binnenraum: auf H\u246 \'f6he der Initiale mehrere vertikale Parallelf\u228 \'e4den mit au\u223 \'dfen anhaftenden Einzelperlen.}

