\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ornamentale Initialen in Deckfarben und Gold}}\plain \f1\lang1033\fs24 : 2\endash 4-zeilige Initialen (H\u246 \'f6he: 1\endash 2 cm) mit schlichtem einfarbigen Stamm, der dicht von Wei\u223 \'dflinienfiligran (Fadenranken, Spangen, Kreuzschraffuren, Punkte) \u252 \'fcberzogen ist, vor rechteckigem goldenen gepunzten Feld, dessen linke Senkrechtkante teils vom Buchstabenstamm, teils von Randranken durchbrochen wird, wobei letztere aus mehrfarbigen langgezogenen, wei\u223 \'df konturierten Profilbl\u228 \'e4ttern, bewimperten und gepunzten Goldpollen sowie Tintenfiligran (teils mit kleinen farbigen Punkten und Bl\u228 \'e4ttchen) bestehen. Binnenraum: vegetabile Formen vor goldenem Grund. Farben: Mittelblau, Dunkel- und Hellrot, Dunkelgr\u252 \'fcn, Wei\u223 \'df, Schwarz, Blattgold. }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

