\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24 : 1\endash 2-zeilige rote und blaue Lombarden im Wechsel (Init.-H\u246 \'f6he: 0,5\endash 1,5 cm), mit Fleuronn\u233 \'e9e in der Gegenfarbe. Besatz: blockartig erweitert durch Parallelf\u228 \'e4den, Perlenketten, leiterartiges Gitter, Reihung von Sternbl\u252 \'fcten, Punkte und Zwickelbl\u228 \'e4tter sowie versehen mit Ausl\u228 \'e4ufern als kurze, von den Ecken abgehende, schr\u228 \'e4ge Einzelf\u228 \'e4den. Binnenraum: Fadenspiralen, Knospenfleuronn\u233 \'e9e (ganze und halbe \u196 \'c4hren ohne Mittelrispe), Perlen.}

