\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Pergament}}\plain \f1\lang1033\fs24   (2 Vorsatz- und 2 Nachsatzbl\u228 \'e4tter Papier), {\field{\*\fldinst HYPERLINK "hida://5706[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 II + 242 Bl.}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5360[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 19,5 x 12}}\plain \f1\lang1033\fs24   cm (bei Neubindung im 17. Jh. stark beschnitten). (I+1)\plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24   + III\plain \f1\super\lang1033\fs24 7\plain \f1\lang1033\fs24   + (IV\endash 1)\plain \f1\super\lang1033\fs24 14\plain \f1\lang1033\fs24   + 5 IV\plain \f1\super\lang1033\fs24 54\plain \f1\lang1033\fs24   + (IV\endash 1+4)\plain \f1\super\lang1033\fs24 65\plain \f1\lang1033\fs24   + 3 (IV+1)\plain \f1\super\lang1033\fs24 92\plain \f1\lang1033\fs24   + IV\plain \f1\super\lang1033\fs24 100\plain \f1\lang1033\fs24   + (IV+1)\plain \f1\super\lang1033\fs24 109\plain \f1\lang1033\fs24   + (IV+2)\plain \f1\super\lang1033\fs24 119\plain \f1\lang1033\fs24   + (IV+7)\plain \f1\super\lang1033\fs24 134\plain \f1\lang1033\fs24   + 5 IV\plain \f1\super\lang1033\fs24 174\plain \f1\lang1033\fs24   + (IV+1)\plain \f1\super\lang1033\fs24 183\plain \f1\lang1033\fs24   + 2 IV\plain \f1\super\lang1033\fs24 199\plain \f1\lang1033\fs24   + (IV+1)\plain \f1\super\lang1033\fs24 208\plain \f1\lang1033\fs24   + (IV\endash 1+2)\plain \f1\super\lang1033\fs24 217\plain \f1\lang1033\fs24   + (IV+2)\plain \f1\super\lang1033\fs24 227\plain \f1\lang1033\fs24   + (IV+1)\plain \f1\super\lang1033\fs24 236\plain \f1\lang1033\fs24   + (II+2)\plain \f1\super\lang1033\fs24 242\plain \f1\lang1033\fs24   + 2 Nachsatzbl\u228 \'e4tter. Schriftspiegel: 10 x 7 cm. 1 Spalte. 18 Zeilen (2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 7\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Ausnahme: 14 x 8,5\endash 9 cm; bis zu 34 Zeilen). {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Abgerundete gotische Minuskel}}\plain \f1\lang1033\fs24   ({\field{\*\fldinst HYPERLINK "hida://5704[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Rotunda}}\plain \f1\lang1033\fs24 ) von einer Haupthand (Kalender und wenige Erg\u228 \'e4nzungen von anderen H\u228 \'e4nden). Rubriziert. Kapitel\u252 \'fcberschriften in Gold. Vorderer und hinterer Spiegel Marmorpapier. {\field{\*\fldinst HYPERLINK "hida://5300[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Goldschnitt}}\plain \f1\lang1033\fs24 . }

