\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Hinweis auf Inhalt. I\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Sophronius Eusebius Hieronymus, Vita Lucretii (wenige Zeilen). 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 144\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Titus Lucretius Carus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De rerum natura}}\plain \f1\lang1033\fs24   (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 22\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24  Buch 1; 22\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 45\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24  Buch 2;  \plain \f1\super\lang1033\fs24  \plain \f1\lang1033\fs24  45\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 66\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24  Buch 3; 67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 92\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24  Buch 4; 92\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 121\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch 5; 121\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 144\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch 6). 145\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant.  }

