\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bernhard von Kraiburg}}\plain \f1\lang1033\fs24   besa\u223 \'df eine Reihe von Hss. aus Padua, die um 1430 angefertigt wurden. Der Clm 5445 war wohl sp\u228 \'e4testens 1454 in seinem Besitz. Alle Details der Hs. \endash  wie das Wasserzeichen, das fast gleiche Format und vor allem der \u228 \'e4hnliche Stil der ornamentalen Initialen sowie die nachtr\u228 \'e4glich (vielleicht von Bernhard von Kraiburg?) eingef\u252 \'fcgten Elemente \endash  stimmen mit dem {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Clm 5451}}\plain \f1\lang1033\fs24   (Kat. 99; siehe dortige Bewertung) \u252 \'fcberein. }

