\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Kleine {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24 : 1\endash 3-zeilige rote und blaue Lombarden im Wechsel (Init.-H\u246 \'f6he: 1\endash 2 cm), mit rosafarbenem Fleuronn\u233 \'e9e. Besatz und Binnnenraum: zahlreiche vertikale Parallelf\u228 \'e4den mit au\u223 \'dfen anhaftenden Perlen unterschiedlicher Gr\u246 \'f6\u223 \'dfe, teils nach links mit waagrecht abstehenden langen Schlaufen; links nach oben und unten leicht verl\u228 \'e4ngert und \endash  \u252 \'fcberlagert von schr\u228 \'e4gstehenden S-Kringeln \endash  in gerade Einzelf\u228 \'e4den auslaufend.}

