\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24 : 2\endash 3-zeilige rote \endash  vereinzelt auch gr\u252 \'fcne (z. B. Bl. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \endash  Lombarden (H\u246 \'f6he: 1\endash 1,5 cm) mit braunem Fleuronn\u233 \'e9e (selten gr\u252 \'fcnes Fleuronn\u233 \'e9e, z. B. VIII\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ). Besatz: seitlich mehrere vertikale bzw. oben querliegende Parallelf\u228 \'e4den mit au\u223 \'dfen anhaftenden Perlenketten (Perlen oft mit Kern) sowie an den Initialecken gr\u246 \'f6\u223 \'dfere Voluten, von denen nach oben und unten Fleuronn\u233 \'e9est\u228 \'e4be (ebenfalls gerade Parallelf\u228 \'e4den, beidseitig mit Perlenketten) ausgehen, die \endash  durch Staubf\u228 \'e4den, Perlenpyramiden oder Einzelgruppe von dichten Medaillons mit Knospenfleuronn\u233 \'e9e (z. B. Bl. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) unterbrochen \endash  in mehrere Einzelf\u228 \'e4den mit starken Kurven, Kringeln und Einrollungen enden. Binnenraum: vertikale Parallelstege mit au\u223 \'dfen anhaftenden Perlen (einzeln, als Pyramiden) oder konturbegleitender Steg und unregelm\u228 \'e4\u223 \'dfige Medaillons mit Knospenfleuronn\u233 \'e9e (B\u252 \'fcschel). 107\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Ausnahme: 14-zeilige blaue Initiale (H\u246 \'f6he: 6,5 cm) mit wei\u223 \'dfen Aussparungen (intermittierende Blattranke, M\u228 \'e4ander) und braunem sowie rotem Fleuronn\u233 \'e9e (Besatz wie oben, wobei links neben der Initiale teilweise braune kompakte Kreissegmente und Perlen das darunterliegende rote Fleuronn\u233 \'e9e \u252 \'fcberdecken).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 @Arial Unicode MS;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

