\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24   (z. B. 4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 14\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ): 6\endash 10-zeilige rote und blaue Lombarden (im Stamm geometrische Aussparungen) in unregelm\u228 \'e4\u223 \'dfigem Wechsel, die roten Initialen mit lilafarbenem und die blauen mit rotem Fleuronn\u233 \'e9e (Init.-H\u246 \'f6he: 3\endash 4,5 cm). Besatz und Binnenraum: jeweils 4 oder 6 vertikal verlaufende Parallelf\u228 \'e4den in Initialh\u246 \'f6he, au\u223 \'dfen mit anhaftenden Perlen (einzeln oder pyramidale Dreiergruppe mit kurzem Stiel), links nach oben und unten verl\u228 \'e4ngert und in Einzelf\u228 \'e4den mit Knick oder Schlaufe in kurze waagrechte F\u228 \'e4den auslaufend.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Aufwendigere\plain \f1\scaps\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initiale}}\plain \f1\lang1033\fs24 : 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Textbeginn unter halbseitiger Aussparung (f\u252 \'fcr nicht ausgef\u252 \'fchrte Miniatur) mit einer aufwendigeren Fleuronn\u233 \'e9e-Initiale (13-zeilig; H\u246 \'f6he: 5 cm) mit ornamental gespaltenem, rot-blauem Stamm. Roter Besatz: blockartig erweitertes Initialfeld, von St\u228 \'e4ben und auf zwei Seiten durchg\u228 \'e4ngig von Perlen (Pyramiden aus jeweils 3 Perlen) ges\u228 \'e4umt, in den Zwickeln Knospendolden und Sternbl\u252 \'fcten, links zus\u228 \'e4tzlich rechteckige Felder, darin Blattranken; nach oben und unten \endash  \u252 \'fcber getreppten Sockel geleitete \endash  lange Ausl\u228 \'e4ufer aus geraden Parallelf\u228 \'e4den, die beidseitig mit Perlenpyramiden und geschwungenen, kurzen Fadenranken besetzt sind und am Ende in gegabelte Ranken mit Dreiergruppe aus Bl\u228 \'e4ttern und Bl\u252 \'fcten enden. Binnenraum: zwei gro\u223 \'dfe, axialsymmetrisch angeordnete Dolden aus gekr\u228 \'e4uselten Knospen.}

