\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24   (ab 185\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ): 4\endash 5-zeilige rote und blaue Lombarden im Wechsel (Init.-H\u246 \'f6he: 1,5\endash 2 cm), mit lilafarbenem bzw. rotem Fleuronn\u233 \'e9e. Besatz und Binnenraum: in Initialh\u246 \'f6he mehrere vertikale Parallelstege mit au\u223 \'dfen anhaftenden Einzelperlen sowie links oben und unten schr\u228 \'e4ge H\u228 \'e4kchen oder Schlaufen als Abschluss.}

