\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24 : 4\endash 6-zeilige rote und blaue Lombarden im Wechsel (Init.-H\u246 \'f6he: 1,5\endash 2,5 cm), mit rosafarbenem Fleuronn\u233 \'e9e. Besatz und Binnenraum: Auf Initialh\u246 \'f6he vertikale Parallelstege (bis zu 8) mit au\u223 \'dfen anhaftenden Einzelperlen (in der Mitte auf Oval [meist mit Kern] ausgedehnt), links nach oben oft Einzelschlaufe bildend und nach unten verl\u228 \'e4ngert \endash  \u252 \'fcberschnitten von einem S-H\u228 \'e4kchen oder schr\u228 \'e4gen Faden \endash  in Einzelf\u228 \'e4den (auch mit Haarnadelkurve) auslaufend.}

