\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : Ia\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacant. I\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   nachgetragenes Lobgedicht auf Raimundus Lullus (18. Jh.; zitiert von \plain \f1\scaps\lang1033\fs24 Perarnau\plain \f1\lang1033\fs24 ). 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 46\plain \f1\super\lang1033\fs24 v\plain \f1\b\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Raimundus Lullus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ars compendiosa inveniendi veritatem}}\plain \f1\lang1033\fs24 . 47\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 50\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. Siehe \plain \f1\scaps\lang1033\fs24 Perarnau\plain \f1\lang1033\fs24 .}

