\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Register zu Petrarca. 2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 144\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Francesco Petrarca}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De remediis utriusque fortunae}}\plain \f1\lang1033\fs24 . 144\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 145\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ps.-Seneca}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De remediis fortuitorum}}\plain \f1\lang1033\fs24 . 146\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 147\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Marcus Tullius Cicero}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Somnium Scipionis}}\plain \f1\lang1033\fs24 . 148\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 151\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Francesco Petrarca, {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Historia Griseldis}}\plain \f1\lang1033\fs24 . 152\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Antonius Cermisonus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Consilia medica duo}}\plain \f1\lang1033\fs24 . 152\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 153\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Chronikalische Notizen. 153\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. Siehe \plain \f1\scaps\lang1033\fs24 Glauche\plain \f1\lang1033\fs24   2011.}

