\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Besitzvermerk aus Dillingen. I\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash II\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   mehrere, schwer lesbare Eintr\u228 \'e4ge auf Rasur. 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Teil eines unbestimmten Verses. 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Publius Ovidius Naso, Versus (Beginn); kaum entzifferbare quer- und kopfst\u228 \'e4ndige Eintr\u228 \'e4ge. 2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Frontispiz (s. u.) und Titel. 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Carmina Vergiliana (Ausschnitt). 3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 17\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Publius Vergilius Maro}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bucolica}}\plain \f1\lang1033\fs24 . 18\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 22\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Publius Vergilius Maro, {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Moretum}}\plain \f1\lang1033\fs24 . 22\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 23\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 60\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Publius Vergilius Maro, {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Georgica}}\plain \f1\lang1033\fs24   (4 B\u252 \'fccher). 62\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   anonyme italienische Poesie (Non posso senza morte contemplarte), nachgetragen. 63\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 172\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Publius Vergilius Maro, {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Aeneis (9 B\u252 \'fccher)}}\plain \f1\lang1033\fs24 .}

