\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Goldinitialen in Wei\u223 \'dfranken}}\plain \f1\lang1033\fs24 : 2\endash 3-zeilige Initialen (H\u246 \'f6he: 1\endash 2 cm) mit goldenem Stamm, umflochten von Wei\u223 \'dfranken (bianchi girari), die meist in querstehende Profilbl\u228 \'e4tter enden und vor rosafarbenen und gr\u252 \'fcnen (teils lindgr\u252 \'fcnen) Parzellen stehen; insgesamt sind sie eingebettet in blaue, \u252 \'fcberwiegend rechteckige Felder (Streumuster: Dreipunkte). 4 leer gebliebene Freir\u228 \'e4ume f\u252 \'fcr solche Initialen: 185\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 185\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 189\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 196\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 . Au\u223 \'dferdem gro\u223 \'dfe Initialen (H\u246 \'f6he: bis zu 6 cm), gro\u223 \'dfenteils mit seitlichen Ausl\u228 \'e4ufern nach oben und unten, jeweils in gr\u246 \'f6\u223 \'dfere vegetabile Konstellation m\u252 \'fcndend. Zwei Initialen jeweils mit Putto: 189\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   bianchi girari und darinsitzender Putto; 195\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   unterhalb der Initiale steht auf angedeuteten blauen Wolken ein kleiner Putto mit Korallenkette und greift nach oben in die Wei\u223 \'dfranken. Farben: Blau, Gr\u252 \'fcn, Rosa, Hellrot, Gelb, Inkarnat, Ocker, Wei\u223 \'df, Braun, Blattgold.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 @Arial Unicode MS;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

