\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Mittelbrauner Ledereinband}}\plain \f1\lang1033\fs24   mit {\field{\*\fldinst HYPERLINK "hida://5300[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Streicheisenlinien}}\plain \f1\lang1033\fs24   (2 Streifenrahmen [innerer trapezf\u246 \'f6rmig]; hinterer Deckel: Mittelfeld in kleines Rautenmuster unterteilt) und {\field{\*\fldinst HYPERLINK "hida://5300[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18 Einzelstempeln}}\plain \f1\lang1033\fs24   (Laubst\u228 \'e4be mit Astgabel, Laubstab mit 6-bl\u228 \'e4ttriger Bl\u252 \'fcte mit 1 oder 2 Blattkr\u228 \'e4nzen und Zwischenbl\u228 \'e4ttern, 6-bl\u228 \'e4ttrige kreisf\u246 \'f6rmige Rosette mit einem Blattkranz und Zwischenbl\u228 \'e4ttern [\u228 \'e4hnlich EBDB s018341; Passau, Meister der Blumengebinde: w002301], diagonal gestelltes Vierblatt ohne Zwischenbl\u228 \'e4tter), deutsch, 15./16. Jh. Hinterer Deckel vertikal gebrochen. Alte Beschl\u228 \'e4ge aus Messing (5- und 6-bl\u228 \'e4ttrige Bl\u252 \'fcten). Am R\u252 \'fccken altes Bibliotheksschildchen.}

