\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacat. I\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Schenkungsvermerk (s. o.). II\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   sp\u228 \'e4teres Inhaltsverzeichnis. II\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash III\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. IV\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Besitzvermerk und eingeklebtes kleines Wappen von Guadagni (s. o.). IV\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kalendarium}}\plain \f1\lang1033\fs24 . 7\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacat. 7\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Miniatur (s. u.). 8\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 88\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Marienmesse}}\plain \f1\lang1033\fs24 . 88\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 89a\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. 89b\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 119\plain \f1\super\lang1033\fs24 r {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Passionsmesse}}\plain \f1\lang1033\fs24 . 119\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 123\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   kleine {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kreuzm