\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24  (z. B. 36\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 41\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ): 5\endash 6-zeilige rote und blaue Lombarden (Init.-H\u246 \'f6he: 2\endash 2,5 cm), mit rotem Fleuronn\u233 \'e9e. Besatz und Binnenraum: Mehrere vertikal (manchmal durch blockartige Erweiterung der Initiale auch horizontal) ausgerichtete Parallelf\u228 \'e4den mit au\u223 \'dfen anhaftenden Punkten und Einzelperlen, unterhalb des Initialstamms meist durch mehrere querstehende Parallelf\u228 \'e4den unterbrochen, in Einzelf\u228 \'e4den mit Endkurve \endash  manchmal auch in Staubfaden \endash  auslaufend.}

