\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt \plain \f1\lang1033\fs24  der Inkunabel: I\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes Andreae}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Lectura arboris consanguinitatis et affinitatis}}\plain \f1\lang1033\fs24 . 4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 144\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17\cf1 Bonifatius VIII., Papa}}\plain \f1\lang1033\fs24\cf1 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17\cf1 Liber sextus decretalium}}\plain \f1\lang1033\fs24\cf1 . 144\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1  vacat. 145\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  Tabula. 145\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1 \endash 146\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24   vacant. \endash  Venedig ({\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Nicolaus Jenson}}\plain \f1\lang1033\fs24 ), 1476. Siehe BSB-Ink B\endash 705,2.}

