\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Gro\u223 \'dfe\plain \f1\scaps\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Goldinitialen vor Wei\u223 \'dfranken und Deckfarben}}\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24  (Farben wie kleine Goldinitialen): 20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 41\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 61\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 80\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 101\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Beginn der Kom\u246 \'f6dien mit 3\endash 4-zeiligen Initialen mit goldenem, schwarz und gelb schattiertem Stamm (Init.-H\u246 \'f6he: 1,5 cm) vor sich verzweigenden Wei\u223 \'dfranken (bianchi girari) mit kleinen Knollen, die sich auf wechselnden Farbparzellen mit Streumuster (Dreipunktgruppen) ranken, zum \u228 \'e4u\u223 \'dferen Kontur hin mehrbl\u228 \'e4ttrige Abzweigungen bilden, sich auf der linken Seite nach oben und unten zu kurzen Ausl\u228 \'e4ufern weiterentwickeln und meist in einer gr\u246 \'f6\u223 \'dferen Blattkonstellation mit spitzen Lappen enden; alles wird unregelm\u228 \'e4\u223 \'dfig von schmalem blauen Grund und wenig feinem Fleuronn\u233 \'e9e mit verstreuten bewimperten Goldpollen umrandet.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

