\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash II\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 38\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Albius Tibullus}}\plain \f1\lang1033\fs24 ,{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  Elegiae}}\plain \f1\lang1033\fs24   (4 B\u252 \'fccher). 38\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 42\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Publius Ovidius Naso}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Epistula Sapphus}}\plain \f1\lang1033\fs24 . 43\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 88\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Publius Ovidius Naso, {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ars amatoria}}\plain \f1\lang1033\fs24   (43\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 57\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch I, 57\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 73\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch II, 73\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 88\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch III). 88\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. Zum Inhalt siehe \plain \f1\scaps\lang1033\fs24 Kn\u246 \'f6dler\plain \f1\lang1033\fs24 .}

