\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant. a\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash c\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Inhalts\u252 \'fcbersicht (a\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash b\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   bis Bl. 46\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  ; c\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   bis Bl. 77\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ). d\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 46\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Anonym, {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bellum Jugurthinum}}\plain \f1\lang1033\fs24   von Sallust\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  (\u220 \'dcbersetzung von Bartolomeo da San Concordio?\plain \f1\scaps\lang1033\fs24 ).\plain \f1\lang1033\fs24   46\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 47\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 53\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Leonardo Bruni}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Difensione}}\plain \f1\lang1033\fs24 . 53\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 54\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Gedichte}}\plain \f1\lang1033\fs24 . 55\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 77\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Anonym, {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Verschw\u246 \'f6rung des Catilina von Sallust}}\plain \f1\lang1033\fs24   (\u220 \'dcbersetzung). 77\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Quintus Tullius Cicero}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Erste catilinarische Rede}}\plain \f1\lang1033\fs24   (italienische \u220 \'dcbersetzung). 92\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 97\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24  Leonardo Bruni, {\field{\*\fldinst HYPERLINK "hida://bezwrk[5].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Vita di Dante Alighieri}}\plain \f1\lang1033\fs24 . 97\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 100\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Idem, {\field{\*\fldinst HYPERLINK "hida://bezwrk[6].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Vita di Francesco Petrarca}}\plain \f1\lang1033\fs24 . 100\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 101\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Gedicht. 101\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 103\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. Siehe auch \plain \f1\scaps\lang1033\fs24 von Reinhardst\plain \f1\scaps\lang1033\fs24 \u246 \'f6\plain \f1\scaps\lang1033\fs24 ttner\plain \f1\lang1033\fs24 .}

