\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24   Titel (= altes Titelblatt). I\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash IV\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Jacobus de Dinanto, {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Expositio in rhetoricam Ciceronis}}\plain \f1\lang1033\fs24 . 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 63\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Marcus Tullius Cicero}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Rhetorica ad Herennium}}\plain \f1\lang1033\fs24   (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 8\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch 1;   (8\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 23\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch 2; 23\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 34\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch 3; 35\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 63\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch 4). 63\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Colores et effectus rhetoricae}}\plain \f1\lang1033\fs24 . 64\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 71\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant.}

