\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacat (oben: nicht lesbarer Eintrag in brauner Tinte [s. o.]; Buchstaben und Zahlen in Bleistift). 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 7\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Sibilla Eritrea Babilonia, Prophetien. 7\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 15\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Testamentum duodecim patriarcharum}}\plain \f1\lang1033\fs24 . 16\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant. 17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 31\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Basilius Caesariensis}}\plain \f1\lang1033\fs24 ,{\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  De studiis}}\plain \f1\lang1033\fs24   (lateinische \u220 \'dcbersetzung von Leonardus Aretinus). 31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 32\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 62\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Speculum ecclesiae}}\plain \f1\lang1033\fs24 . 62\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 110\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bonaventura Sanctus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Itinerarium mentis in Deum}}\plain \f1\lang1033\fs24 . 110\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 134\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[5].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Officium sanctae crucis}}\plain \f1\lang1033\fs24 . 134\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 135\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacant. 135\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   sp\u228 \'e4terer, schwer lesbarer Eintrag (auf hinterem Spiegel transkribiert): \plain \f1\i\lang1033\fs24  Fur cave ne nostrum tangat tua dextera librum. Namque [\u8230 \'85] ligni[\u8230 \'85]lla tenenda dabis\plain \f1\lang1033\fs24 .}

