\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 81\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Alexander Aphrodisiensis}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 In Aristotelis librum de sensu commentarium}}\plain \f1\lang1033\fs24 . 82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 168\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Michael Ephesius}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kommentare zu Aristoteles}}\plain \f1\lang1033\fs24   (jeweils zu diversen Schriften: 82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 104\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  ; 104\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 114\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  ; 114\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 123\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  ; 124\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 129\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  ; 129\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 145\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  ; 145\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 152\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  ; 152\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 168\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ). 169\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 180\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Proclus Diadochus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Institutio physica}}\plain \f1\lang1033\fs24 . Siehe \plain \f1\scaps\lang1033\fs24 Hajd\plain \f1\scaps\lang1033\fs24 \u249 \'f9\plain \f1\lang1033\fs24 .}

