\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt:\plain \f1\lang1033\fs24   4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 5\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. 5a\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 5b\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   eingelegte Bl\u228 \'e4tter aus einem Verzeichnis (alphabetisch). 5b\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 5d\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. 5f\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Inhalts\u252 \'fcberblick. 5f\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 328\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bartolus de Saxoferrato}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 In Digestum novum}}\plain \f1\lang1033\fs24   (157\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   datiert {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1457}}\plain \f1\lang1033\fs24   in Perugia; 158\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 163\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant; 328\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   datiert {\field{\*\fldinst HYPERLINK "hida://5060[1].5064/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 1458}}\plain \f1\lang1033\fs24   in Perugia, siehe Provenienz). 329\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 331\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant.}

