\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Pergament}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5706[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 II + 149 Bl.}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5360[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 28 x 18,5}}\plain \f1\lang1033\fs24   cm. (I\endash 1)\plain \f1\super\lang1033\fs24 I\plain \f1\lang1033\fs24   + (V+1)\plain \f1\super\lang1033\fs24 10\plain \f1\lang1033\fs24  + 13 V\plain \f1\super\lang1033\fs24 140\plain \f1\lang1033\fs24   + IV\plain \f1\super\lang1033\fs24 148\plain \f1\lang1033\fs24   + (I\endash 1)\plain \f1\super\lang1033\fs24 149\plain \f1\lang1033\fs24 . Schriftspiegel: 18,5 x 10,5 cm. 1 Spalte. 34 Zeilen. \plain \f1\lang1033\fs24\chcbpat17  {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Humanistische Kursive}}\plain \f1\lang1033\fs24   von einer Hand. Auf Bl. II\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   und 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   oben goldene Capitalis. Kapitel\u252 \'fcberschriften und einzelne Namen am Rand in roter Tinte, weitere kurze Randnotizen in brauner Tinte, wenig sp\u228 \'e4ter. Recto- und Versoseite oben mit Seitentitel in Rot (Buchz\u228 \'e4hlung). Vorderer und hinterer Spiegel Pergament. {\field{\*\fldinst HYPERLINK "hida://5300[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Goldschnitt}}\plain \f1\lang1033\fs24   (Rautenmuster durch Perlenschn\u252 \'fcre).}

