\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Titel (nur Petrarca genannt). 1\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24  datierter Vorspann (1304) f\u252 \'fcr eine Ostertafel (fragmentiert). 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 39\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Petrarca}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Sine nomine}}\plain \f1\lang1033\fs24   (= 19 anonyme Briefe). 39\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   Hieronymus (Exzerpte). 39\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 40\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Bertoldo Lavazola, Epitaph f\u252 \'fcr Nicol\u242 \'f2 Lavazola. 40\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   verschiedene kurze Verse. 41\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 52\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Albertino Mussato}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ecerinis}}\plain \f1\scaps\lang1033\fs24  (\plain \f1\lang1033\fs24  siehe\plain \f1\scaps\lang1033\fs24  H. M\plain \f1\scaps\lang1033\fs24 \u252 \'fc\plain \f1\scaps\lang1033\fs24 ller\plain \f1\lang1033\fs24 , Fr\u252 \'fcher Humanismus in Oberitalien. Albertino Mussato: Ecerinis [Studien zur klassischen Philologie 31]. Frankfurt a. M. [u. a.] 1987, S. 96-176). 53\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   Zitate. 54\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 57\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Mondkalender (Januar bis Juli). 58\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 67\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Rufius Festus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Breviarium rerum gestarum populi Romani}}\plain \f1\lang1033\fs24 . 67\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Exzerpte. 68\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Hinweis auf Petrus von Moglio und dessen Argumente zu den Trag\u246 \'f6dien des Seneca. 68\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 69\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Sentenzen und Exzerpte. 69\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 71\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Fortsetzung des Mondkalenders (August bis Dezember). 72\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacat. 72\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   r\u246 \'f6mische Zahlen. Siehe \plain \f1\scaps\lang1033\fs24 Sottili\plain \f1\lang1033\fs24 . }

