\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant. II\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24  kurzer Inhalts\u252 \'fcberblick. II\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   sp\u228 \'e4tere Eintr\u228 \'e4ge (Bibliotheksvermerk und Sterbenotiz f\u252 \'fcr Schreiber). 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 65\plain \f1\super\lang1033\fs24 r{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  Leo I., Papa}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Sermones}}\plain \f1\lang1033\fs24 . 65\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 68\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Idem, {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Epistolae}}\plain \f1\lang1033\fs24 . 68\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 126\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Gregorius I., Papa}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Sermones}}\plain \f1\lang1033\fs24 . 127\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 129\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Thascius Caecilius Cyprianus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De mortalitate}}\plain \f1\lang1033\fs24 . 130\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs2