\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   (= Vorsatz) vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Notizen zu De oratore und Besitzeintrag (s. o.). 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Inhalt (von sp\u228 \'e4terer Hand). 1a\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 187\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Marcus Tullius Cicero}}\plain \f1\lang1033\fs24   (1a\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 9\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Laelius de amicitia}}\plain \f1\lang1033\fs24  ; 10\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 10\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Epistolae ad Atticum}}\plain \f1\lang1033\fs24   (Exzerpt); 10\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 24\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De senectute}}\plain \f1\lang1033\fs24  ; 25\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Paradoxa}}\plain \f1\lang1033\fs24  ; 31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 38\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Timaeus}}\plain \f1\lang1033\fs24  ; 38\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 45\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[5].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De fato}}\plain \f1\lang1033\fs24  ; 45\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 106\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[6].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De oratore}}\plain \f1\lang1033\fs24  ; 106\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 118\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[7].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Orator}}\plain \f1\lang1033\fs24  ; 118\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 137\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[8].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Orationes IV in Catilinam}}\plain \f1\lang1033\fs24  ; 137\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 163\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[9].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Lucullus}}\plain \f1\lang1033\fs24  ; 163\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 187\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[10].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De legibus}}\plain \f1\lang1033\fs24 ). 188\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacat. 188\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   beschnittene Notizen. 189\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   (= Nachsatz) vacant. Siehe \plain \f1\scaps\lang1033\fs24 Hauke\plain \f1\lang1033\fs24 .