\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\chcbpat8\cf18 Miniatur\plain \f1\lang1033\fs24   (121\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ): {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kanonbild}}\plain \f1\lang1033\fs24 . Ganzseitige Darstellung (Ma\u223 \'dfe: 21 x 15 cm) der {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kreuzigung Christi}}\plain \f1\lang1033\fs24   (Dreifigurenschema mit Maria und dem hl. Johannes) in rot/goldenem Rahmen. Das Kreuz \endash  es schlie\u223 \'dft oben unmittelbar an den Rahmen an und durchzieht fast die gesamte H\u246 \'f6he der Szene \endash  steht auf einem kleinen felsigen Wulst inmitten einer gr\u252 \'fcnen Wiese, die am vorderen Bildrand aufgeworfen ist, und tr\u228 \'e4gt den sehr fein gestalteten K\u246 \'f6rper des mit einem Leinentuch bekleideten Christus, aus dessen Brust, H\u228 \'e4nden und F\u252 \'fc\u223 \'dfen Blut tropft. Neben ihm stehen links die hl. Maria mit schwarzem Mantel \u252 \'fcber rotem Kleid, die H\u228 \'e4nde angstvoll ausgebreitet, und rechts der betende hl. Johannes (roter Mantel \u252 \'fcber gr\u252 \'fcnem Kleid) mit ge\u246 \'f6ffnetem Mund und bek\u252 \'fcmmertem Gesicht.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 @Arial Unicode MS;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

