\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Titelminiatur in Deckfarben und Gold}}\plain \f1\lang1033\fs24 : 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   illuminierter Titel, der auf allen vier Seiten aus einer golden und hellbraun umrandeten Leiste besteht, in der sich gleichm\u228 \'e4\u223 \'dfig goldene Blattranken mit andersfarbigen Bl\u252 \'fcten vor braunem Grund entwickeln; seitlich sind in schmalen Ovalfeldern die golden modellierten Reliefs der zueinander gewandten Profile von links einem trompetenden Putto sowie rechts einer jungen m\u228 \'e4nnlichen B\u252 \'fcste (Andreas Bragadino?) gezeigt, w\u228 \'e4hrend man oben und unten \endash  jeweils in querst\u228 \'e4ndigen, zus\u228 \'e4tzlich mit Rundbogen ausgeweiteten Ovalen \endash  den Markusl\u246 \'f6wen und am Fu\u223 \'df der Seite das vor einer Landschaft mit Bergen h\u228 \'e4ngende Wappen des Andrea Bragadino (durch rotes Kreuz geviertes Schild, obere Felder blau, untere Felder einst silbern [heute oxydiert]) sehen kann; im mittigen Schriftraum ist oben in einem roten Queroval in goldener Capitalis der Doge selbst genannt (\plain \f1\i\lang1033\fs24  Nos Andreas Griti Dei gratia dux Venetiarum etc.\plain \f1\lang1033\fs24 ), darunter ist auf einem an den R\u228 \'e4ndern lila schattierten Pergamentfeld die Widmung an \plain \f1\i\lang1033\fs24  Andrea Bragadeno\plain \f1\lang1033\fs24   in humanistischer Kursive zu lesen. Farben: verschiedene Gr\u252 \'fcn- und Blaut\u246 \'f6ne, Hellrot, Lila, Rosa, Hell- und Dunkelbraun, Wei\u223 \'df, Schwarz, Silber und Pinselgold.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Zeichnung: 25\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   unten kopfst\u228 \'e4ndig an den Schriftspiegel angeh\u228 \'e4ngter kleiner H\u252 \'fcgel, auf dem eine Schwalbe steht, die in souver\u228 \'e4ner Technik in brauner {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Tinte}}\plain \f1\lang1033\fs24   gezeichnet und ebenfalls kopfst\u228 \'e4ndig als \plain \f1\i\lang1033\fs24  Hirundo\plain \f1\lang1033\fs24   (= Schwalbe) benannt wird (Ma\u223 \'dfe: 4 x 8,5 cm). M\u246 \'f6glicherweise befand sich auch am Fu\u223 \'df von Bl. 16 eine \u228 \'e4hnliche Zeichnung, weshalb dort der Streifen unterhalb des Textes abgeschnitten wurde.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

